//
//   - url:   a GitHub issue or pull request URL
//   - short: owner/repo#N shorthand, or "owner/repo #N"
//   - repo:  owner/repo followed by a word that marks a repo, not a
//     path: "PR", "issue", "pull request", "changelog", "release", a
//     version or "("
